'use strict';
function reliabilitySettings(){const p=profile();return `<section class="section"><h2>During your workout</h2><p class="small">These settings apply to this profile.</p><div class="setting-row"><div><strong>Keep screen awake</strong><p class="small muted" id="wake-status">${esc(wakeStatus)}</p></div><button data-action="toggle-awake" aria-pressed="${p.preferences?.keepAwake!==false}">${p.preferences?.keepAwake===false?'Off':'On'}</button></div><div class="setting-row"><div><strong>Compact training view</strong><p class="small muted">One active movement with all five within reach.</p></div><button data-action="toggle-compact" aria-pressed="${p.preferences?.compact!==false}">${p.preferences?.compact===false?'Off':'On'}</button></div></section><section class="section"><h2>Offline & updates</h2><p class="small" id="offline-detail">${esc(runtimeStatus())}</p><p class="small muted">Open once online and wait for “Offline copy ready” before training without a connection. Device storage can still be cleared by your browser.</p><button data-action="update-app" style="margin-top:16px">Check for updates</button></section><section class="section"><h2>Backups & recovery</h2><p class="small" id="storage-health">${esc(storageHealth)}</p><p class="small muted">Profiles, workouts and history stay on this device. The safety copy is local too. A downloaded backup is the way to keep your data if this browser is cleared.</p><p class="small">${p.lastExportAt?`Last export: ${new Date(p.lastExportAt).toLocaleDateString('en-GB')}`:'No backup exported yet.'}</p><div class="builder-actions"><button class="primary" data-action="export-backup">Export backup</button><label class="file-button">Import backup<input type="file" id="backup-file" accept="application/json,.json" ${hasActive()?'disabled':''}></label><button data-action="recover-copy" ${hasActive()?'disabled':''}>Restore safety copy</button><button data-action="persistent-storage">Protect local storage</button></div><button class="danger-button" data-action="delete-data" style="margin-top:20px">Delete all local data</button></section>`;}
function trainingView(s,rows){
 const i=Math.max(0,Math.min(4,s.activeSlot||0)),m=rows[i].main;
 return `<section class="training-screen"><div class="training-top"><div><span class="eyebrow">${esc(s.type)} · ${i+1} / 5</span><h1>Training</h1></div><button data-action="focus">Show full workout</button></div><div class="training-clock"><div><span class="small muted">Time remaining</span><strong id="timer" role="timer">20:00</strong></div><div class="timer-controls"><button class="primary" id="start-btn" data-action="start">${s.running?'Pause':'Resume'}</button><button data-action="reset">Reset</button></div><span id="timer-status" class="small">${s.running?'Running':'Paused'}</span><span class="session-rep-total">${countTotal(repEntries(s))} reps${countTotal(repEntries(s),'sec')?` · ${countTotal(repEntries(s),'sec')}s holds`:''}</span><div class="timer-dial" hidden></div><div class="progress" role="progressbar" aria-label="Session progress" aria-valuemin="0" aria-valuemax="1200" aria-valuenow="0"><i id="timer-bar"></i></div></div><div class="move-selector" role="group" aria-label="Choose active movement">${rows.map((r,n)=>`<button data-action="active-move" data-i="${n}" aria-pressed="${n===i}" class="${n===i?'selected':''}"><span>${n+1}</span><small>${esc(r.main.name)}</small></button>`).join('')}</div>${exercise(rows[i],i,s)}<div class="training-next"><p class="small muted">${i===4?'Next: start again at movement 1':`Next: ${esc(rows[i+1].main.name)}`}</p><button class="primary" data-action="next-move">${i===4?'Back to movement 1':'Next movement'} →</button></div><p class="small muted counting-note">Count left and right together. Add reps with +1, +5 or +10; holds use seconds. Move on when your set is done.</p><details class="training-echo"><summary>Previous workout comparison</summary>${echoPanel(s,rows)}</details><div class="sound-state-row"><span class="small muted" id="sound-state"></span><button id="sound-enable" data-action="enable-audio">Enable finish sound</button></div><p class="small muted" id="wake-status">${esc(wakeStatus)}</p></section>`;
}
function showDeleteConfirmation(all){modal(`<h2>${all?'Delete all local data?':'Delete this profile?'}</h2><p>${all?'All profiles, saved workouts, safety copies and training history on this device will be removed.':'This profile and its workouts and training history will be removed.'} Download an export first if you want to keep a copy.</p><div class="builder-actions"><button data-action="close">Cancel</button><button data-action="export-backup">Export backup</button><button class="danger-button" data-action="${all?'confirm-delete-data':'confirm-delete-profile'}">Delete permanently</button></div>`);}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,p=profile(),s=activeSession();
 if(a==='active-move'&&hasActive()){s.activeSlot=Number(b.dataset.i);openAlts.clear();persist();render();}
 if(a==='next-move'&&hasActive()){s.activeSlot=((s.activeSlot||0)+1)%5;openAlts.clear();persist();render();}
 if(a==='toggle-awake'||a==='toggle-compact'||a==='toggle-sound'){
  p.preferences??={};const key={'toggle-awake':'keepAwake','toggle-compact':'compact','toggle-sound':'sound'}[a];p.preferences[key]=p.preferences[key]===false;persist();render();syncSessionRuntime();
 }
 if(a==='enable-audio'){await setupAudio();syncFinishAudio();paintRuntimeStatus();}
 if(a==='export-backup')exportBackup();
 if(a==='confirm-import')restoreBackup();
 if(a==='recover-copy'){
  if(hasActive())return;const recovered=readStoredState(RECOVERY_KEY);if(!recovered){toast('No valid safety copy is available. Import a downloaded backup instead.');return;}
  pendingRestore=migrateState(recovered);modal('<h2>Restore the local safety copy?</h2><p>This restores the previous saved state across all profiles. Export your current data first if you want to keep it.</p><div class="builder-actions"><button data-action="close">Cancel</button><button data-action="export-backup">Export current data</button><button class="primary" data-action="confirm-import">Restore safety copy</button></div>');
 }
 if(a==='delete-data')showDeleteConfirmation(true);
 if(a==='delete-profile')showDeleteConfirmation(false);
 if(a==='confirm-delete-data')deleteLocalData();
 if(a==='confirm-delete-profile'){
  cancelFinishAudio();state.profiles=state.profiles.filter(x=>x.id!==p.id);if(!state.profiles.length)state.profiles=[newProfile('My profile')];state.active=state.profiles[0].id;
  try{localStorage.removeItem(RECOVERY_KEY);}catch{}saveState(migrateState(state),{backup:false});day=hasActive()?activeSession().day:defaultWorkoutIndex();focusMode=false;document.querySelector('#modal').close();render();syncSessionRuntime();toast('Profile deleted.');
 }
 if(a==='update-app')updateOfflineApp();
 if(a==='persistent-storage'){
  const nav=browserNavigator();try{const protectedStorage=await nav.storage?.persist?.();toast(protectedStorage?'Browser storage protection enabled. Keep exporting backups too.':'Storage protection was not granted. Keep a downloaded backup.');}catch{toast('Storage protection is unavailable. Keep a downloaded backup.');}
 }
});
document.addEventListener('change',e=>{if(e.target.dataset.load!==undefined)saveLoad(Number(e.target.dataset.load),e.target.value);if(e.target.id==='backup-file')previewImport(e.target.files[0]);});
